(()=>{'use strict';
const label={nameA:'队伍 A 全名',nameB:'队伍 B 全名',shortA:'队伍 A 简称',shortB:'队伍 B 简称',logoA:'队伍 A 标识',logoB:'队伍 B 标识',scoreA:'队伍 A 小局比分',scoreB:'队伍 B 小局比分',mapName:'地图名称',mapIcon:'地图图标',bp:'地图 BP',replay:'Replay',radar:'Radar',scoredeck:'赛程 / 展示',title:'标题',round:'轮次',timer:'倒计时',text:'文字',image:'图片',video:'视频'};
const mapKey=v=>String(v||'').toLowerCase().replace(/^.*\//,'').replace(/^de_/,'').replace(/[^a-z0-9]/g,'').replace(/^dustii$/,'dust2');
const mapImage=v=>'/assets/maps/'+mapKey(v)+'.svg';
let root,snapshot=null,nodes=new Map(),items=[],offset=0,pending=false,playlistMode='';const preview=new URLSearchParams(location.search).has('preview');
const css=document.createElement('link');css.rel='stylesheet';css.href='/assets/halftime/highlights.css';document.head.append(css);
function resize(){if(root)root.style.transform=`translate(-50%,-50%) scale(${Math.min(innerWidth/1920,innerHeight/1080)})`;}
function clear(){for(const s of nodes.values()){s.video?.pause();s.box.remove();}nodes.clear();}
function frame(s,url){const f=document.createElement('iframe');f.src=url;f.allow='autoplay';f.title=label[s.e.type];s.box.append(f);s.frame=f;}
function stop(){if(root)root.hidden=true;for(const s of nodes.values())s.video?.pause();}
function render(data){const active=data.customLayout||data.mode==='full';if(!active){stop();return false;}snapshot=data;offset=data.serverTime-Date.now();if(!root){root=document.createElement('div');root.id='highlight-stage';document.body.append(root);}
 const mode=data.mode==='full'?'full':'half',p=data.layouts[mode],auto=location.pathname==='/output/halftime-auto';root.hidden=auto&&!data.auto?.active;if(root.hidden){stop();return true;}root.style.backgroundColor=p.transparent?'transparent':p.background;root.style.backgroundImage=p.backgroundImage?`url(${JSON.stringify(p.backgroundImage)})`:'';
 if(playlistMode!==mode){items=[];playlistMode=mode;clear();void poll();}
 const ids=new Set(p.elements.map(e=>e.id));for(const [id,s]of nodes)if(!ids.has(id)){s.video?.pause();s.box.remove();nodes.delete(id);}
 p.elements.forEach((e,index)=>{let s=nodes.get(e.id),key=JSON.stringify([e.type,e.source,e.scene,e.half,e.layer,e.fade,e.showPlayers,data.radar.outputUrl]);if(s&&s.key!==key){s.video?.pause();s.box.remove();nodes.delete(e.id);s=null;}if(!s){s={key,e,box:document.createElement('div')};s.box.className='highlight-element';s.box.dataset.type=e.type;s.box.dataset.id=e.id;root.append(s.box);nodes.set(e.id,s);
 if(['replay','video'].includes(e.type)){const v=document.createElement('video');v.playsInline=true;v.preload='auto';v.onerror=()=>{v.style.visibility='hidden';};v.onloadeddata=()=>{v.style.visibility='visible';};s.video=v;s.box.append(v);if(preview&&e.type==='replay'){s.empty=document.createElement('div');s.empty.className='highlight-empty';s.empty.textContent='REPLAY · 等待当前地图的击杀视频';s.box.append(s.empty);}if(e.type==='video')v.src=e.source;}
 else if(e.type==='radar'){const u=new URL(data.radar.outputUrl);for(const [k,v]of Object.entries({embed:'halftime',parent:location.origin,half:e.half,layer:e.layer,fade:e.fade,players:e.showPlayers?'1':'0'}))u.searchParams.set(k,v);frame(s,u.href);}
 else if(e.type==='scoredeck')frame(s,location.origin+'/output/'+e.scene+'?preview=1&halftimeEmbed=1');
 else if(['image','logoA','logoB','mapIcon'].includes(e.type)){s.img=new Image();s.img.onerror=()=>{s.img.hidden=true;};s.img.onload=()=>{s.img.hidden=false;};s.box.append(s.img);}
 else {s.content=document.createElement('div');s.box.append(s.content);}}
 s.e=e;Object.assign(s.box.style,{left:e.x+'px',top:e.y+'px',width:e.w+'px',height:e.h+'px',fontSize:e.fontSize+'px',color:e.color,opacity:e.opacity,zIndex:index});const r=data.resolved;
 if(s.video){s.video.muted=preview||e.muted;s.video.style.objectFit=e.fit;s.video.playbackRate=e.speed;}
 if(s.img){const src=e.type==='image'?e.source:e.type==='mapIcon'?mapImage(r.map):r[e.type];if(src&&s.img.getAttribute('src')!==src){s.img.hidden=false;s.img.src=src;}else if(!src)s.img.hidden=true;s.img.style.objectFit=e.fit;}
 if(s.frame){const fw=e.type==='radar'?1024:1920,fh=e.type==='radar'?1024:1080,scale=e.fit==='cover'?Math.max(e.w/fw,e.h/fh):Math.min(e.w/fw,e.h/fh);Object.assign(s.frame.style,{width:fw+'px',height:fh+'px',transform:`translate(-50%,-50%) scale(${e.fit==='fill'?e.w/fw:scale},${e.fit==='fill'?e.h/fh:scale})`});}
 if(s.content&&e.type!=='timer'){if(e.type==='bp'){s.content.className='highlight-bp';s.content.replaceChildren(...(r.bp||[]).filter(v=>v.map).map(v=>{const box=document.createElement('div'),im=new Image(),cap=document.createElement('small');im.src=mapImage(v.map);const team=side=>r[side==='A'?'shortA':'shortB']||('队伍 '+side);cap.textContent=`${v.team?team(v.team)+' ':''}${v.action.toUpperCase()}`;if(['pick','decider'].includes(v.action)){const picker=v.sidePicker,side=v.startSide;cap.textContent+=picker&&side?` · ${team(picker)} ${side} / ${team(picker==='A'?'B':'A')} ${side==='CT'?'T':'CT'}`:' · 选边待定';}box.className=v.action;box.append(im,cap);return box;}));}else s.content.textContent=e.type==='title'?e.text||(mode==='full'?'全场精选':data.config.title):e.type==='text'?e.text:r[e.type]??'—';}
 });resize();tick();return true;}
function sync(v,t,running,loop){if(!v.getAttribute('src')||!Number.isFinite(v.duration)||v.duration<=0)return;let target=t/1000;if(loop)target%=v.duration;else target=Math.min(target,v.duration-.04);if(Math.abs(v.currentTime-target)>.45)try{v.currentTime=Math.max(0,target);}catch{}if(running&&(loop||t<v.duration*1000)){if(v.paused)v.play().catch(()=>{});}else v.pause();}
function tick(){if(!snapshot||!root||root.hidden)return;const c=snapshot.config.media,now=Date.now()+offset,t=c.offsetMs+(c.status==='running'?Math.max(0,now-c.startAt):0),running=c.status==='running';for(const s of nodes.values()){const e=s.e;if(e.type==='timer'){const clock=snapshot.config.clock,n=Math.ceil(Math.max(0,clock.status==='running'?clock.endAt-now:clock.remainingMs)/1000);s.content.textContent=n?`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`:snapshot.config.endText;}
 if(e.type==='radar')s.frame?.contentWindow?.postMessage({type:'scoredeck-halftime-clock',elapsedMs:t*e.speed,playing:running,loop:e.loop},new URL(snapshot.radar.outputUrl).origin);
 if(e.type==='video')sync(s.video,t*e.speed,running,e.loop);
 if(e.type==='replay'){if(window.SDObsPlayback?.replay(s,e.id,e.speed))continue;const valid=items.filter(v=>v.duration>0),total=valid.reduce((n,v)=>n+v.duration*1000,0);if(s.empty)s.empty.hidden=!!total;if(c.status==='running'&&c.offsetMs===0&&s.epoch!==c.startAt){s.epoch=c.startAt;s.replayBase=null;}if(!total){s.video.pause();s.video.style.visibility='hidden';continue;}if(s.replayBase==null)s.replayBase=t;let pos=Math.max(0,t-s.replayBase)*e.speed;if(e.loop)pos%=total;else if(pos>=total){s.video.pause();s.video.style.visibility='hidden';continue;}for(const v of valid){if(pos<v.duration*1000){if(s.clip!==v.id){s.clip=v.id;s.video.src='/api/halftime/replay/media/'+encodeURIComponent(v.id)+'?mode='+playlistMode;}s.video.style.visibility='visible';sync(s.video,pos,running,false);break;}pos-=v.duration*1000;}}
 }}
async function poll(){if(pending||!snapshot||root?.hidden)return;pending=true;const mode=playlistMode;try{const d=await(await fetch('/api/halftime/replay?mode='+mode,{cache:'no-store'})).json();if(mode===playlistMode)items=d.items||[];}catch{}finally{pending=false;}}
window.SDHighlights={render,labels:label,mapImage};addEventListener('resize',resize);setInterval(tick,100);setInterval(poll,1500);
})();
